import java.util.*;

class Solution {
  public String minimizeStringValue(String s) {
    char[] a = s.toCharArray();
    int[] cnt = new int[26];
    for (char c : a) if (c != '?') cnt[c - 'a']++;
    List<Integer> pos = new ArrayList<>(), pick = new ArrayList<>();
    for (int i = 0; i < a.length; i++)
      if (a[i] == '?') {
        int z = 0;
        for (int j = 1; j < 26; j++) if (cnt[j] < cnt[z]) z = j;
        cnt[z]++;
        pos.add(i);
        pick.add(z);
      }
    Collections.sort(pick);
    for (int i = 0; i < pos.size(); i++) a[pos.get(i)] = (char) ('a' + pick.get(i));
    return new String(a);
  }
}
